# region: emit
def emit(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: shape
def shape(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: digest
def digest(xs, floor_=6):
    return [v for v in xs if v >= floor_]

# region: fold
def fold(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) // n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: gather
def gather(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return gather(fold(digest(shape(emit(raw)))))

